from pathlib import Path
import sympy as s,mpmath as mp,json,re
mp.mp.dps=65;R=s.Rational;x=s.symbols('x',real=True);b=Book('3.8',[283,284,285]);records=[]
def m(z):return r'\('+z+r'\)'
def F(z):return(m(z),m(z))
def tx(z):return s.latex(z)
def num(z,d=6):return f'{float(z):.{d}f}'
def add(n,k,e,steps,ak,ae=None,parts=[]):
 b.add(n,283 if n<=12 else 284 if n<=38 else 285,('뉴턴 방법','Newton’s Method'),(k,e),steps,(ak,ak if ae is None else ae),parts,check=('초기값·분모의 도함수·정의역을 확인하고 수렴값을 원래 방정식에 대입한다. 모든 근을 요구하면 근의 개수도 별도로 확인한다.','Check the starting value,derivative denominator,and domain.Substitute the limit into the original equation;when all roots are requested,verify their count separately.'));b.E[n]['conceptHref']='../../calc1/index.html'
def newton(n,f,seed,count=None):
 df=s.diff(f,x);ff=s.lambdify(x,f,'mpmath');dd=s.lambdify(x,df,'mpmath');v=mp.mpf(str(s.N(seed,65)));seq=[v]
 for j in range(count-1 if count else 1000):
  slope=dd(v);assert slope!=0,(n,v);u=v-ff(v)/slope;seq.append(u)
  if count is None and abs(u-v)<mp.mpf('1e-50'):break
  v=u
 else:
  if count is None:raise ValueError(('no convergence',n))
 if count is None:assert abs(ff(seq[-1]))<mp.mpf('1e-45'),(n,ff(seq[-1]))
 records.append({'exercise':n,'seed':str(seed),'iterations':[mp.nstr(v,25)for v in seq],'residual':mp.nstr(ff(seq[-1]),6),'fixedIterationCount':count})
 return seq
rule=F(r'x_{n+1}=x_n-{f(x_n)\over f^{\prime}(x_n)}')
add(1,'그림에서 x₁=6으로 오른쪽 근 s를 찾는다. (a)접선으로 x₂,x₃를 추정하고 (b)x₁=8이 더 나은지 설명하라.','For the supplied graph,start at x₁=6 to find the right root s.(a)Draw Newton tangents and estimate x₂,x₃.(b)Would x₁=8 be better?', [rule,('x=6의 접선이 가로축과 만나는 점은 약7.3,그곳의 접선은 약6.8에서 축과 만난다.','The tangent at6 meets the axis near7.3;the next tangent meets it near6.8.'),('8은 근 오른쪽의 위로 오목한 부분에 있어 접선 절편들이 근의 오른쪽에서 가까워진다. 6에서의 비교적 작은 기울기 때문에 생기는 첫 과대 이동을 피한다.','At8 the point is on the concave-up branch to the right of the root,so tangent intercepts approach from that side.This avoids the initial overshoot caused by the smaller slope at6.')],'(a)x₂≈7.3,x₃≈6.8; (b)예.','(a)x₂≈7.3,x₃≈6.8;(b)Yes.',list('ab'))
add(2,'같은 그림에서 x₁=1로 왼쪽 근 r을 찾을 때 접선을 그리고 x₂,x₃를 추정하라.','On the same graph,use x₁=1 to find the left root r.Draw tangents and estimate x₂,x₃.',[rule,('x=1에서 f≈1.8~1.9,기울기≈−0.8로 읽으면 첫 절편은 약3.3이다. 이 점에서 접선을 다시 그리면 약2.8이다.','Reading f(1)≈1.8–1.9 and slope≈−0.8 gives a first intercept near3.3.The next tangent intercept is near2.8.'),('그림에서 읽는 값이므로 수십분의 일 정도 달라질 수 있다.','These are graphical estimates and may vary by a few tenths.')],'x₂≈3.3,x₃≈2.8.','x₂≈3.3,x₃≈2.8.')
add(3,'(2,5)에서의 접선이 y=9−2x이다. 뉴턴 방법의 x₁=2일 때 x₂를 구하라.','The tangent at(2,5)is y=9−2x.With x₁=2,find x₂.',[F(r'f(2)=5,\quad f^{\prime}(2)=-2'),F(r'x_2=2-{5\over-2}=9/2')],m('x_2=4.5'))
add(4,'주어진 그래프에서 초기값 (a)0,(b)1,(c)3,(d)4,(e)5를 쓰면 뉴턴 방법이 어떻게 되는지 설명하라.','For the supplied graph,describe Newton’s method from(a)0,(b)1,(c)3,(d)4,(e)5.', [('(a)접선 절편이 점점 왼쪽으로 가며 근을 향하지 않는다.','(a)Tangent intercepts move left,away from a root.'),('(b)(d)1과4에서는 수평접선이므로 도함수 분모가0이 되어 진행할 수 없다.','(b)(d)Horizontal tangents at1 and4 give a zero denominator.'),('(c)3에서는 왼쪽 근 약2로,(e)5에서는 오른쪽 근 약6으로 접근한다.','(c)From3 the iterations approach the left root near2;(e)from5 they approach the right root near6.')],'(a)실패; (b)미정의; (c)왼쪽 근; (d)미정의; (e)오른쪽 근.','(a)Fails;(b)undefined;(c)left root;(d)undefined;(e)right root.',list('abcde'))
add(5,'0에 닿는 주어진 곡선에서 초기값 a,b,c,d 중 뉴턴 방법이 근0으로 수렴할 것으로 보이는 것을 골라라.','For the supplied curve touching the axis at0,which starting points a,b,c,d appear to converge to0?', [('a,b,c의 접선 절편은 더 가까운 중앙 영역으로 돌아온다. d는 기울기가 너무 작아 먼 반대편으로 튀고 이후에도 근을 벗어나는 것으로 보인다.','Tangents from a,b,c return to the nearer central region.At d the small slope sends the intercept far to the opposite side,and subsequent tangents appear to move away.'),('그림에 근거한 판단이며 함수식 없는 일반 수렴 정리는 아니다.','This is a graphical judgment,not a general convergence theorem without a formula.')],'a,b,c.',parts=[])
for n,f,seed in[(6,2*x**3-3*x*x+2,-1),(7,2/x-x*x+1,2),(8,x**5-x*x-1,1),(9,x**3+x+3,-1),(10,x**4-x-1,1)]:
 count=3 if n<=8 else 2;seq=newton(n,f,seed,count);ans=m('x_'+str(count)+'='+num(seq[-1],4));steps=[rule,F('f(x)='+tx(f)+r',\quad f^{\prime}(x)='+tx(s.diff(f,x))),F(r',\quad '.join('x_'+str(j+1)+'='+mp.nstr(v,12)for j,v in enumerate(seq)))]
 if n>=9:steps.append(F('y='+tx(s.expand(f.subs(x,seed)+s.diff(f,x).subs(x,seed)*(x-seed)))));steps.append(('마지막 식은 첫 접선이며 그 x절편이 x₂이다.','The last equation is the first tangent;its x-intercept is x₂.'))
 add(n,m('f(x)='+tx(f)+',\quad x_1='+str(seed))+'에서 '+('x₃를 소수 넷째 자리까지 구하라.'if n<=8 else'x₂를 구하고 첫 접선과 함수 그래프로 설명하라.'),'For '+m('f(x)='+tx(f)+',\quad x_1='+str(seed))+', '+('find x₃ to four decimals.'if n<=8 else'find x₂ and illustrate the first tangent.'),steps,ans)
