for n,(f,seeds,places,k,e,why,whye)in cases.items():
 roots=[];steps=[rule,F('f(x)='+tx(f)+r',\quad f^{\prime}(x)='+tx(s.diff(f,x)))]
 for seed in seeds:
  seq=newton(n,f,seed);roots.append(seq[-1]);shown=seq[:5]+([seq[-1]]if len(seq)>5 else[]);steps.append(F('x_1='+tx(s.sympify(seed))+r':\quad '+r'\to '.join(mp.nstr(v,12)for v in shown)))
 steps.append((why,whye));answer=m(',\quad '.join(num(v,places)for v in roots))
 if n in[20,22,23,24]:assert s.Poly(f,x).count_roots(-s.oo,s.oo)==len(roots)
 add(n,m('f(x)='+tx(f))+'에 뉴턴 방법을 적용하여 '+k+'를 소수 '+str(places)+'자리까지 구하라.','Use Newton’s method for '+m('f(x)='+tx(f))+' to find '+e+' to '+str(places)+'decimal places.',steps,answer,parts=list('ab')if n in[13,14]else[])
