for seed in seeds:
 seq=newton(19,f,seed);roots.append(seq[-1]**3);steps.append(F('u_1='+tx(seed)+r'\Longrightarrow u\approx'+mp.nstr(seq[-1],14)+r'\Longrightarrow x\approx'+num(seq[-1]**3)))
assert s.Poly(f,x).count_roots(-s.oo,s.oo)==2
steps.append(('u=0은 근이 아니며, u의 실근2개가 x의 서로 다른 두 실근에 대응한다.','u=0 is not a root,and the two real u-roots correspond to two distinct real x-roots.'))
add(19,m(r'1/x=\sqrt[3]x-1')+'의 모든 실근을 소수 여섯 자리까지 뉴턴 방법으로 구하라.','Find all real roots of '+m(r'1/x=\sqrt[3]x-1')+' to six decimals using Newton’s method.',steps,m(',\quad '.join(num(v)for v in roots)))
